/**
 * Write `@dorkos/api-client`'s generated files from `docs/api/openapi.json`.
 *
 * Two files, both committed and both compared byte for byte by the
 * `openapi-fresh` check (`.github/workflows/docs-openapi-check.yml`):
 *
 * - `src/generated/openapi.ts`: the document's types, from `openapi-typescript`
 *   (`paths`, `components` and `operations`, the last keyed by operationId).
 * - `src/generated/operation-routes.ts`: each operationId's method and path, the
 *   one fact the types cannot carry to run time.
 *
 * Run with `pnpm api-client:generate`; `pnpm docs:export-api` runs it after it
 * writes the document, so the two never drift apart.
 *
 * @module api-client/scripts/generate
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString, type OpenAPI3 } from 'openapi-typescript';

const PACKAGE_DIR = join(dirname(fileURLToPath(import.meta.url)), '..');
const REPO_ROOT = join(PACKAGE_DIR, '..', '..');
const DOCUMENT_PATH = join(REPO_ROOT, 'docs', 'api', 'openapi.json');
const OUT_DIR = join(PACKAGE_DIR, 'src', 'generated');

/** Every path in the document hangs off this mount; the client's `baseUrl` stands for it. */
const API_MOUNT = '/api';

const METHODS = ['get', 'put', 'post', 'delete', 'patch', 'head', 'options'] as const;

const HEADER = `// Generated by \`pnpm api-client:generate\` from docs/api/openapi.json. Do not edit.
// The openapi-fresh check fails when this file differs from a fresh run.
`;

/** One operation's place in the document, as the route table records it. */
interface Route {
  operationId: string;
  method: string;
  path: string;
}

/** Each operation's method and path, sorted by operationId; throws on a gap or a clash. */
function routesOf(document: OpenAPI3): Route[] {
  const routes = new Map<string, Route>();
  for (const [path, item] of Object.entries(document.paths ?? {})) {
    if (!path.startsWith(`${API_MOUNT}/`)) {
      throw new Error(`${path} is not under ${API_MOUNT}; the client's baseUrl cannot reach it.`);
    }
    for (const method of METHODS) {
      const operation = (item as Record<string, { operationId?: string } | undefined>)[method];
      if (!operation) continue;
      const { operationId } = operation;
      if (!operationId) throw new Error(`${method.toUpperCase()} ${path} has no operationId.`);
      if (routes.has(operationId)) throw new Error(`operationId ${operationId} is used twice.`);
      routes.set(operationId, {
        operationId,
        method: method.toUpperCase(),
        path: path.slice(API_MOUNT.length),
      });
    }
  }
  return [...routes.values()].sort((a, b) => (a.operationId < b.operationId ? -1 : 1));
}

/** The route table's source text. */
function routeTableSource(routes: Route[]): string {
  const rows = routes.map(
    (route) =>
      `  ${JSON.stringify(route.operationId)}: { method: ${JSON.stringify(route.method)}, path: ${JSON.stringify(route.path)} },`
  );
  return `${HEADER}import type { operations } from './openapi.js';

/** Each operation's HTTP method and its path under the API mount (\`${API_MOUNT}\`), by operationId. */
export const OPERATION_ROUTES = {
${rows.join('\n')}
} as const satisfies Record<keyof operations, { method: string; path: string }>;
`;
}

const document = JSON.parse(readFileSync(DOCUMENT_PATH, 'utf8')) as OpenAPI3;
const types = astToString(await openapiTS(document, { silent: true }));

mkdirSync(OUT_DIR, { recursive: true });
const written = [
  ['openapi.ts', `${HEADER}${types}`],
  ['operation-routes.ts', routeTableSource(routesOf(document))],
] as const;
for (const [name, text] of written) writeFileSync(join(OUT_DIR, name), text);
console.log(
  `api-client: wrote ${written.map(([name]) => relative(REPO_ROOT, join(OUT_DIR, name))).join(', ')}`
);
